func ompCatalogFixture(t *testing.T, name string) []byte {
	t.Helper()
	data, err := os.ReadFile("testdata/" + name)
	if err != nil {
		t.Fatal(err)
	}
	return data
}

func TestOMPCompactSourcePreservesStableMetadata(t *testing.T) {
	// The compact fixture was generated by OMP's encodeModelCatalog at blob
	// df9ceaa58e3de5a42ae3c1d3a4c788380aa431f0. The expected snapshot uses
	// Vista's persisted format, which is independent of OMP's source encoding.
	expected, err := decodeOMPCatalog(ompCatalogFixture(t, "omp_snapshot_expected.json"))
	if err != nil {
		t.Fatal(err)
	}
	data := ompCatalogFixture(t, "omp_source_compact_v1.json")
	revision := ompSourceRevision(data)
	original := CurrentOMPCatalog()
	t.Cleanup(original.Activate)
	client := ompDownloadClient(t, revision, string(data))
	transport := client.Transport
	client.Transport = ompTestTransport(func(r *http.Request) (*http.Response, error) {
		if r.URL.Host == "cdn.jsdelivr.net" {
			return &http.Response{StatusCode: 403, Body: io.NopCloser(strings.NewReader("forbidden"))}, nil
		}
		return transport.RoundTrip(r)
	})
	compact, err := FetchOMPCatalog(context.Background(), client)
	if err != nil {
		t.Fatal(err)
	}
	if CurrentOMPCatalog() != original || compact.Info().ModelCount != 4 || compact.Info().ProviderCount != 2 {
		t.Fatal("compact download changed active metadata or lost model counts")
	}
	if !reflect.DeepEqual(expected.data.Providers, compact.data.Providers) {
		t.Fatal("compact decoding changed stable metadata")
	}
	bitmap, ok := compact.model("fixture", "bitmap")
	if !ok || bitmap.Reasoning || bitmap.SupportsTools == nil || !*bitmap.SupportsTools {
		t.Fatalf("boolean fields beyond the first 32-bit word were lost: %+v", bitmap)
	}
	plain, _ := compact.model("opencode", "vista-no-tools")
	if plain.Reasoning || plain.SupportsTools == nil || *plain.SupportsTools || plain.Thinking != nil || plain.ContextWindow != 0 || plain.MaxTokens != 0 {
		t.Fatalf("false booleans or unknown limits were changed: %+v", plain)
	}
	for _, id := range []string{"vista-catalog-fixture", "vista-shared"} {
		model, ok := compact.model("opencode", id)
		if !ok || model.Thinking == nil || model.Thinking.DefaultLevel != "max" || model.Thinking.EffortMap["max"] != "xhigh" || !model.Thinking.SupportsDisplay || !model.Thinking.RequiresEffort {
			t.Fatalf("shared thinking metadata was changed: %+v", model)
		}
	}
	dir := t.TempDir()
	if err := compact.Save(dir); err != nil {
		t.Fatal(err)
	}
	if err := LoadOMPCatalog(dir); err != nil || OMPCatalogRevision() != revision {
		t.Fatalf("compact catalog could not be reloaded: %v", err)
	}
	cached, err := os.ReadFile(OMPCatalogPath(dir))
	if err != nil || strings.Contains(string(cached), "runtime-only-field") || strings.Contains(string(cached), `"compat"`) || strings.Contains(string(cached), `"cost"`) {
		t.Fatalf("compact source leaked runtime fields into the saved snapshot: %v", err)
	}
}

func TestOMPCompactSourceRejectsMalformedData(t *testing.T) {
	fixture := ompCatalogFixture(t, "omp_source_compact_v1.json")
	original := CurrentOMPCatalog()
	for name, mutate := range map[string]func(map[string]any){
		"missing-version": func(s map[string]any) { delete(s, "version") },
		"version":         func(s map[string]any) { s["version"] = 2 },
		"null-version":    func(s map[string]any) { s["version"] = nil },
		"providers":       func(s map[string]any) { s["providers"] = []any{} },
		"keys":            func(s map[string]any) { s["keys"] = []any{} },
		"shapes":          func(s map[string]any) { s["booleanShapes"] = []any{} },
		"nodes":           func(s map[string]any) { s["nodes"] = []any{} },
		"reference": func(s map[string]any) {
			s["providers"].([]any)[0].([]any)[1] = []any{1000000}
		},
		"fractional-reference": func(s map[string]any) {
			s["providers"].([]any)[0].([]any)[1] = []any{0.5}
		},
		"undefined-object": func(s map[string]any) {
			s["providers"].([]any)[0].([]any)[1] = []any{-1}
		},
		"duplicate-provider": func(s map[string]any) {
			providers := s["providers"].([]any)
			s["providers"] = append(providers, providers[0])
		},
		"duplicate-model": func(s map[string]any) {
			provider := s["providers"].([]any)[0].([]any)
			rows := provider[2].([]any)
			provider[2] = append(rows, rows[0])
		},
		"identity": func(s map[string]any) {
			s["providers"].([]any)[0].([]any)[0] = "wrong-provider"
		},
		"boolean-mask": func(s map[string]any) {
			nodes := s["nodes"].([]any)
			provider := s["providers"].([]any)[0].([]any)
			node := nodes[int(provider[1].([]any)[0].(float64))].([]any)
			node[3].([]any)[0] = float64(4294967296)
		},
		"cyclic-node": func(s map[string]any) {
			nodes := s["nodes"].([]any)
			ref := s["providers"].([]any)[0].([]any)[1].([]any)
			node := nodes[int(ref[0].(float64))].([]any)
			node[1] = []any{float64(0), ref}
		},
		"node-type": func(s map[string]any) {
			nodes := s["nodes"].([]any)
			ref := s["providers"].([]any)[0].([]any)[1].([]any)
			nodes[int(ref[0].(float64))].([]any)[0] = float64(2)
		},
		"odd-properties": func(s map[string]any) {
			nodes := s["nodes"].([]any)
			ref := s["providers"].([]any)[0].([]any)[1].([]any)
			nodes[int(ref[0].(float64))].([]any)[1] = []any{float64(0)}
		},
	} {
		t.Run(name, func(t *testing.T) {
			var source map[string]any
			if err := json.Unmarshal(fixture, &source); err != nil {
				t.Fatal(err)
			}
			mutate(source)
			data, err := json.Marshal(source)
			if err != nil {
				t.Fatal(err)
			}
			if _, err := decodeOMPSourceCatalog(data, "fixture"); err == nil || CurrentOMPCatalog() != original {
				t.Fatalf("invalid compact source was accepted or replaced the active catalog: %v", err)
			}
		})
	}
}

func TestOMPSourceRejectsLegacyFormat(t *testing.T) {
	_, err := decodeOMPSourceCatalog([]byte(`{"fixture":{"model":{"id":"model","provider":"fixture","name":"Model","api":"openai-completions","input":["text"]}}}`), "fixture")
	if err == nil || !strings.Contains(err.Error(), "unsupported OMP catalog version") {
		t.Fatalf("legacy source did not fail with a version error: %v", err)
	}
}
